import React, { useState, useEffect } from 'react';

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('http://localhost:8000/api/comandes') // URL de tu API
      .then(res => {
        if (!res.ok) throw new Error('Error al obtenir les comandes');
        return res.json();
      })
      .then(data => {
        setOrders(data.dades || []); // usamos "dades" que devuelve la API
        setLoading(false);
      })
      .catch(err => {
        console.error('Error fetching orders:', err);
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div className="row">
      {orders.map(order => (
        <div key={order.id} className="col-md-6 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">Client: {order.nom_client}</h5>
              <p className="card-text"><strong>Total:</strong> {order.total}€</p>
              <p className="card-text"><strong>Estat:</strong> {order.estat}</p>
              <p className="card-text"><strong>Data:</strong> {new Date(order.created_at).toLocaleDateString('ca-ES')}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default OrdersList;
